"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["38686"],{63816(e,t,s){s.d(t,{Ay:()=>r,RM:()=>o});var n=s(74848),i=s(28453);let o=[];function a(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"if-you-eat-salted-fish-be-ready-for-the-thirst",children:"If You Eat Salted Fish, Be Ready for the Thirst"})}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"2007/9/3 15:38:43"}),"\n"]}),"\n",(0,n.jsxs)("div",{style:{color:"#FF0000",fontWeight:"500"},children:[(0,n.jsx)(t.p,{children:"A trip to Guangdong always teaches you some quirky Chinese expressions, like today's title. The meaning of this saying, applied to today's market participants, couldn't be more apt."}),(0,n.jsx)(t.p,{children:"Today's broader market, as discussed last Friday: with no news of sufficient weight over the weekend, bullish energy erupted as expected. But today brought an interesting phenomenon\u2014the market lingered below 5330 for a long time, refusing to go up. Why? Because the memory of what was left behind above 4330 remains too vivid."}),(0,n.jsx)(t.p,{children:"Now, every day is essentially a bet\u2014betting that no significant news will come out that evening. The key issue is that the confidentiality of policy decisions has exceeded most people's imagination. Otherwise, how could May 29th possibly have been the highest close? Thus, the biggest contradiction shaping current price action is the tension between still-strong market energy and the fear of sudden news."}),(0,n.jsx)(t.p,{children:"In this situation, one must embrace the spirit of \"if you eat salted fish, be ready for the thirst.\" Go hard or go home\u2014charge until the news breaks. When the real deal drops, smash without mercy and see who's tougher. Even during the 530 crash, plenty of individual stocks were still in the green that morning. The key is to never hesitate when it's time to sell. Only then do you earn the right to keep being reckless. Otherwise, step aside and watch."}),(0,n.jsx)(t.p,{children:"Recklessness requires qualification. Without the temperament, without the technique, don't be reckless. Earth is too dangerous\u2014go back to Mars. And the current recklessness is proceeding entirely according to script: second- and third-tier stocks are dancing wildly. Some people clamor that they'd rather have a blue-chip bubble than let second- and third-tier stocks move\u2014that's textbook water-in-the-brain thinking. Reality has already punished these people harshly enough."}),(0,n.jsx)(t.p,{children:"From a pure technical standpoint, today's gap creates a short-term oscillation risk, and therefore the technical significance of this gap must be taken seriously in the short term."}),(0,n.jsx)(t.p,{children:"For individual stocks, one can fully focus on the significance of the technical chart. Using stocks this ID holds as examples:"}),(0,n.jsx)(t.p,{children:"The first category, like 600636, belongs to the weakest stocks\u2014still hasn't gotten back above the half-year line. The task for such stocks is to first hold above the half-year line and then expand from there. Specifically for this stock, there are no fundamental problems\u2014it's just that there are too many mixed players inside."}),(0,n.jsx)(t.p,{children:"The second category, like 600737\u2014just broke through the first rebound high after May 30th a few days ago, then pulled back. This holds the same significance for other stocks. The task for this category is to stabilize at that level through oscillation, and only then will it go challenge the May 30th highs."}),(0,n.jsx)(t.p,{children:"The third category, like 000938\u2014oscillation after breaking through the May 30th high is perfectly normal. For this category, whether the short-term rally can continue depends critically on whether the May 30th high can hold firm after the oscillation."}),(0,n.jsx)(t.p,{children:"For catch-up second- and third-tier stocks, these are the only three categories. Therefore, you can handle them with appropriate short-term strategies based on specific conditions. If you can't figure it out or don't have time for short-term trading, just use the 5-day or 5-week line for entries and exits\u2014that's the laziest method for short- to medium-term operations. Generally, when oscillation occurs at resistance levels, you can exit on the rally and buy back on the dip, using the hub oscillation method. If you lack the judgment and skill for that, forget it."}),(0,n.jsx)(t.p,{children:"Additionally, unless your technique is particularly advanced, frequent trading is not recommended at this time, because nobody can guarantee that what you buy today won't be hit by terrible news that very evening. For those with exceptional mindset and technique, of course it doesn't matter\u2014if real news hits, one slash and it's done. But ordinary people don't have that kind of mentality."}),(0,n.jsx)(t.p,{children:"One must pay attention: long-term entry must occur at a long-term buy point. Entering at a short-term buy point and trying to hold long-term is an absolute violation of this ID's theory. Entry at a short-term buy point only implies short-term trading, unless you have the strongest possible will and can sit through any prison sentence to the end. Otherwise, don't play this game."}),(0,n.jsx)(t.p,{children:"What this ID says is what it is. For example, the current broader market movement is acceptable to this ID. But if the broader market quickly breaks through the 3/4 line and continues rapidly rising to construct a bull trap, then even without policy intervention, this ID will absolutely show no mercy. The recent Chalco play was just a drill. The purpose of this Chalco drill was fully achieved\u2014it successfully enabled the complete switch to second- and third-tier stocks. Starting tomorrow, every man for himself."}),(0,n.jsx)(t.p,{children:"The afternoon and evening are reserved for PE. No choice. Logging off now. See you."})]})]})}function r(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(a,{...e})}):a(e)}},73793(e,t,s){s.r(t),s.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>r,contentTitle:()=>h,toc:()=>c,assets:()=>l});var n=JSON.parse('{"id":"stocks/saltedfish","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/stocks/saltedfish.md","sourceDirName":"stocks","slug":"/stocks/saltedfish","permalink":"/en/stocks/saltedfish","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"saltedfish","title":"","hide_table_of_contents":true,"sidebar_label":"If you eat salted fish, you must endure the thirst (2007/9/3 15:38:43)"},"sidebar":"stocksExtendedSidebar","previous":{"title":"The current stage of the market (2007/9/3 8:49:53)","permalink":"/en/stocks/marketstage"},"next":{"title":"Teaching You Stock Trading 76: Some Anecdotes of Toying with Market Makers 2 (2007/9/3 19:19:43)","permalink":"/en/stocks/076"}}'),i=s(74848),o=s(28453),a=s(63816);let r={id:"saltedfish",title:"",hide_table_of_contents:!0,sidebar_label:"If you eat salted fish, you must endure the thirst (2007/9/3 15:38:43)"},h,l={},c=[...a.RM];function d(e){return(0,i.jsx)(a.Ay,{})}function u(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,t,s){s.d(t,{R:()=>a,x:()=>r});var n=s(96540);let i={},o=n.createContext(i);function a(e){let t=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),n.createElement(o.Provider,{value:t},e.children)}}}]);